import{_ as e,o as t,c as i,a2 as o}from"./chunks/framework.CWgsre3x.js";const h=JSON.parse('{"title":"Ειδοποιήσεις επιβατών και ιστορικό παράδοσης","description":"","frontmatter":{},"headers":[],"relativePath":"el/plus/passenger-notifications.md","filePath":"el/plus/passenger-notifications.md"}'),s={name:"el/plus/passenger-notifications.md"};function l(n,a,r,c,p,d){return t(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="ειδοποιησεις-επιβατων-και-ιστορικο-παραδοσης" tabindex="-1">Ειδοποιήσεις επιβατών και ιστορικό παράδοσης <a class="header-anchor" href="#ειδοποιησεις-επιβατων-και-ιστορικο-παραδοσης" aria-label="Permalink to &quot;Ειδοποιήσεις επιβατών και ιστορικό παράδοσης&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">Έκδοση αναφοράς</p><p>Έλεγχος πηγαίου κώδικα TransferBook+ v0.7.26. Επιβεβαιώστε εγκατεστημένη έκδοση, εταιρεία, δικαιώματα και ρυθμίσεις. Χρησιμοποιήστε εγκεκριμένα συνθετικά δεδομένα για εκπαίδευση. Δεν επιβεβαιώνεται εμπορική ενεργοποίηση.</p></div><h2 id="προετοιμασια-ειδοποιησης" tabindex="-1">Προετοιμασία ειδοποίησης <a class="header-anchor" href="#προετοιμασια-ειδοποιησης" aria-label="Permalink to &quot;Προετοιμασία ειδοποίησης&quot;">​</a></h2><ol><li>Ανοίξτε τον εγκεκριμένο χώρο Notifications και επιλέξτε κράτηση, συμβάν κύκλου ζωής και κανάλι. Επιβεβαιώστε κατάσταση και παραλήπτη.</li><li>Σεβαστείτε συγκατάθεση, εξαίρεση και διαθεσιμότητα καναλιού. Σε κράτηση μόνο με τηλέφωνο μην επινοείτε email. Επιλέξτε εγκεκριμένο διαθέσιμο κανάλι ή αφήστε το μήνυμα χωρίς αποστολή.</li><li>Ελέγξτε ασφαλή προεπισκόπηση επιβάτη. Μην κοινοποιείτε εσωτερικές σημειώσεις, κόστος προμηθευτών, άλλους πελάτες ή περιττά προσωπικά στοιχεία.</li><li>Αποστείλετε μόνο με ρητή έγκριση παρόχου και εταιρείας· η προεπισκόπηση ή αντιγραφή δεν είναι παράδοση.</li></ol><h2 id="ελεγχος-και-επαναληψη" tabindex="-1">Έλεγχος και επανάληψη <a class="header-anchor" href="#ελεγχος-και-επαναληψη" aria-label="Permalink to &quot;Έλεγχος και επανάληψη&quot;">​</a></h2><p>Εξετάστε Notification Delivery Outbox και φίλτρο αποτυχιών. Ελέγξτε προσπάθειες και σφάλμα πριν από επανάληψη. Η μόνιμη ελεγχόμενη επανάληψη απαιτεί δικαίωμα εγγραφής ειδοποιήσεων. Ελέγξτε ξανά εξαίρεση· μην την παρακάμπτετε και μην επαναλαμβάνετε παραδομένο μήνυμα. Σε αναμονή, αποτυχία και μη ρυθμισμένο δεν σημαίνουν απεσταλμένο. Συμφωνήστε με διαθέσιμα τεκμήρια παρόχου.</p><p>Χρησιμοποιήστε συνθετικούς παραλήπτες και απομονωμένες δοκιμές μέχρι έγκριση εξωτερικής αποστολής. Η αυτόματη εξωτερική αποστολή παραμένει απενεργοποιημένη μέχρι ρύθμιση και έγκριση.</p><p>Δείτε <a href="/el/integrations/ai-messaging-setup.html">API AI και μηνυμάτων</a> και <a href="/el/integrations/conversational-booking.html">Κρατήσεις μέσω συνομιλίας</a>.</p>',8)])])}const _=e(s,[["render",l]]);export{h as __pageData,_ as default};
